// Defines the shape of the user data object
export interface UserData {
  day: number;
  month: number;
  year: number;
  gender: string;
}

export type NumerologyData = ReturnType<typeof generateLoShuData>;

/**
 * Generates all numerology data including the Lo Shu Grid and arrows.
 * @param userData - An object with day, month, year, gender.
 * @returns An object containing all calculated results.
 */
export const generateLoShuData = ({ day, month, year, gender }: UserData) => {
  // 1. Calculate all core numbers
  const psycheNum = calculatePsyche(day);
  const destinyNum = calculateDestiny(day, month, year);
  const kuaNum = calculateKua(year, gender);
  
  // Tier 1
  const compoundNum = calculateCompoundNumber(day, month, year);
  const compoundMeaning = COMPOUND_NUMBER_MEANINGS[compoundNum] || "No specific meaning found for this compound number.";

  // Tier 2
  let reducedCompoundNum: number | null = null;
  let reducedCompoundMeaning: string | null = null;
  if (compoundNum >= 10) {
      const reducedNum = reduceToSingleDigit(compoundNum);
      if (COMPOUND_NUMBER_MEANINGS[reducedNum]) {
          reducedCompoundNum = reducedNum;
          reducedCompoundMeaning = COMPOUND_NUMBER_MEANINGS[reducedNum];
      }
  }

  // Tier 3
  const karmicFateNum = calculateKarmicFateNumber(day, month, year);
  const karmicFateMeaning = KARMIC_FATE_MEANINGS[karmicFateNum] || "No specific meaning found for this karmic fate number.";


  // We need the original Kua calculation before it's adjusted for '5' to handle special cases
  let rawKua = reduceToSingleDigit(
    gender.toLowerCase() === 'male' 
      ? (year < 2000 ? 11 - reduceToSingleDigit(String(year).split('').reduce((acc, d) => acc + parseInt(d, 10), 0)) : 9 - reduceToSingleDigit(String(year).split('').reduce((acc, d) => acc + parseInt(d, 10), 0)))
      : (year < 2000 ? 4 + reduceToSingleDigit(String(year).split('').reduce((acc, d) => acc + parseInt(d, 10), 0)) : 6 + reduceToSingleDigit(String(year).split('').reduce((acc, d) => acc + parseInt(d, 10), 0)))
  );

  if (rawKua === 0) rawKua = 9;
  
  // Get Kua Directions
  let auspiciousDirections;
  // Use the raw, pre-adjustment Kua for Kua 5 gender split
  if (rawKua === 5) {
      auspiciousDirections = KUA_DIRECTIONS[5][gender.toLowerCase() as 'male' | 'female'];
  } else {
      auspiciousDirections = KUA_DIRECTIONS[kuaNum];
  }
  
  // Get Kua Attributes
  const kuaAttributes = KUA_ATTRIBUTES[kuaNum] || { element: 'N/A', colors: 'N/A', season: 'N/A' };


  // Aggregate ALL digits for the grid
  const birthDigits = (String(day) + String(month) + String(year))
    .split('')
    .filter(d => d !== '0');
    
  const allDigitsForGrid = [
    ...birthDigits,
    ...String(psycheNum).split(''),
    ...String(destinyNum).split(''),
    ...String(kuaNum).split(''),
  ];
  
  const presentDigits = new Set(allDigitsForGrid.map(d => parseInt(d, 10)));

  // Count frequencies and create grid data
  const counts: { [key: string]: number } = {};
  for (const digit of allDigitsForGrid) {
    counts[digit] = (counts[digit] || 0) + 1;
  }

  const gridContent: { [key: string]: string } = {};
  for (let i = 1; i <= 9; i++) {
    const digitStr = String(i);
    gridContent[digitStr] = counts[digitStr] ? digitStr.repeat(counts[digitStr]) : '';
  }

  // Arrange data into a 2D array for rendering
  const gridLayout = [
    [gridContent['4'], gridContent['9'], gridContent['2']],
    [gridContent['3'], gridContent['5'], gridContent['7']],
    [gridContent['8'], gridContent['1'], gridContent['6']],
  ];

  // Determine present arrows of strength
  const arrowsOfStrength = ARROWS_OF_STRENGTH.filter(arrow => 
    arrow.numbers.every(num => presentDigits.has(num))
  );

  // Determine present arrows of weakness
  const arrowsOfWeakness = ARROWS_OF_WEAKNESS.filter(arrow =>
    arrow.numbers.every(num => !presentDigits.has(num))
  );

  // Return all calculated data
  return {
    psycheNum,
    destinyNum,
    kuaNum,
    compoundNum,
    compoundMeaning,
    reducedCompoundNum,
    reducedCompoundMeaning,
    karmicFateNum,
    karmicFateMeaning,
    loShuGrid: gridLayout,
    allDigitsForGrid: allDigitsForGrid,
    numberCounts: counts,
    arrowsOfStrength,
    arrowsOfWeakness,
    auspiciousDirections,
    kuaAttributes,
  };
};
